1	/**
2	 * Throw gesture: state machine plus the descriptor computed on release.
3	 *
4	 * Two channels leave this module, with deliberately different reliability:
5	 *
6	 *   AIM   — streamed ~20Hz while gripped. Lossy and cosmetic. Dropping every one
7	 *           of these must only make the TV preview stutter, never change a throw.
8	 *   THROW — one authoritative payload on release, computed from the whole swing.
9	 *
10	 * That split is why a network hiccup can never cause a "the game read my throw
11	 * wrong" moment. Keep it: nothing in AIM may feed the simulation.
12	 */
13	
14	import { clamp, normalize01 } from './sensors.js';
15	
16	/**
17	 * Sign that converts device heading into game yaw. This is the one place the two
18	 * coordinate conventions meet, so it is the one place that can get it backwards.
19	 *
20	 * `dYaw` is a compass-style bearing delta from `pointingHeading` — clockwise-positive
21	 * viewed from above. Unity's `Quaternion.AngleAxis(deg, up)` is also clockwise viewed
22	 * from above, taking +Z toward +X. So the two already agree and the default is +1.
23	 *
24	 * (This was -1 while aim came straight from Euler `alpha`, which counts the other way.
25	 * Deriving the heading from the pointing vector changed the handedness of the source
26	 * value, so the correction that used to be needed would now reintroduce the error.)
27	 *
28	 * GAME-SPACE CONTRACT: positive aimDeg means aim to the player's right.
29	 *
30	 * Overridable per-device from the URL (?yawSign=-1) — see setYawSign.
31	 */
32	let yawSign = 1;
33	
34	/** @param {number} sign -1 (default) or +1 */
35	export function setYawSign(sign) {
36	  yawSign = sign < 0 ? -1 : 1;
37	}
38	
39	export function getYawSign() {
40	  return yawSign;
41	}
42	
43	/** Device heading delta -> game yaw. Positive is right. */
44	export function toGameYaw(dYaw) {
45	  return yawSign * dYaw;
46	}
47	
48	export const ThrowTuning = {
49	  // Peak linear acceleration, m/s^2, mapped onto power 0..1. A gentle underarm
50	  // toss sits near the low end; a hard swing saturates the high end.
51	  minPeakAccel: 6,
52	  maxPeakAccel: 35,
53	
54	  // How far from the acceleration peak a release can land before timing quality
55	  // decays to zero. This is the Skip Skimmer "release at the right moment" beat.
56	  peakWindowMs: 250,
57	
58	  // Full rotation. This was 45, which silently threw away the top of every fast
59	  // swing: any turn past 45 degrees flattened to exactly 45, so hard throws all
60	  // reported the same aim no matter where the phone was actually pointing, and the
61	  // rock left on a line the player had not chosen. dYaw is already a shortest-angle
62	  // delta in (-180, 180], so at 180 nothing is clipped and aiming behind you is
63	  // simply allowed — if a player turns right around, that is a choice they made.
64	  maxAimDeg: 180,
65	
66	  minAttackDeg: -60,
67	  maxAttackDeg: 60,
68	
69	  // Below this peak, treat the gesture as a fumble rather than a throw — stops a
70	  // pocket bump or a shaky hand registering as a real attempt.
71	  minValidPeakAccel: 3,
72	
73	  // How far back from the release a swing can reach. Bounded in TIME, not in
74	  // samples: the ring buffer holds a fixed sample count sized for a 60Hz device,
75	  // so on a device reporting at ~30Hz it spans twice as long in wall-clock terms.
76	  // Without this bound such a device can select a "peak" from seconds before the
77	  // swing, which makes releaseDelayMs huge and collapses timingQuality to zero.
78	  swingWindowMs: 1500,
79	};
80	
81	/**
82	 * Shape of a throw synthesized on a device with no motion sensors.
83	 *
84	 * This exists so a desktop browser can occupy a seat during multi-player testing.
85	 * A second phone is the real test; a second PC is the one most people can actually
86	 * arrange, and without this it can join, take its turn, and then deadlock the match
87	 * — the turn only advances when a throw completes.
88	 */
89	export const SimulatedThrow = {
90	  minHoldMs: 150,
91	  maxHoldMs: 1200,
92	  minPower: 0.2,
93	  maxPower: 0.95,
94	
95	  // attackAngleDeg is a delta from the player's grip, and SkipTuning maps a neutral
96	  // grip onto the stone's optimal angle — so 0 is already a good throw. The jitter
97	  // stays well inside the tolerance window so simulated throws skip rather than
98	  // sinking, which would make every test score identically zero.
99	  attackJitterDeg: 6,
100	  aimJitterDeg: 10,
101	  spinRate: 120,
102	  timingQuality: 0.85,
103	};
104	
105	/**
106	 * Build a throw from nothing but how long the button was held.
107	 *
108	 * Pure, and takes its randomness as a parameter, so tests can pin it.
109	 *
110	 * @param {number} holdMs how long the grip was held
111	 * @param {function} random source of 0..1 randomness
112	 */
113	export function computeSimulatedThrowDescriptor(holdMs, random = Math.random) {
114	  const charge = normalize01(holdMs, SimulatedThrow.minHoldMs, SimulatedThrow.maxHoldMs);
115	  const jitter = (range) => (random() * 2 - 1) * range;
116	
117	  return {
118	    power: SimulatedThrow.minPower + charge * (SimulatedThrow.maxPower - SimulatedThrow.minPower),
119	    timingQuality: SimulatedThrow.timingQuality,
120	    aimDeg: jitter(SimulatedThrow.aimJitterDeg),
121	    attackAngleDeg: jitter(SimulatedThrow.attackJitterDeg),
122	    rollDeg: 0,
123	    spinRate: SimulatedThrow.spinRate,
124	
125	    // Zero samples is the tell. A real gesture always has some, so the TV debug
126	    // readout distinguishes a simulated throw from a genuine one at a glance.
127	    peakAccel: 0,
128	    releaseDelayMs: 0,
129	    sampleCount: 0,
130	    simulated: true,
131	  };
132	}
133	
134	export const ThrowState = {
135	  IDLE: 'IDLE',
136	  GRIPPED: 'GRIPPED',
137	};
138	
139	/**
140	 * How the player marks the moment the rock leaves their hand.
141	 *
142	 * HOLD — press and hold, swing, let go. The release is a finger lift.
143	 * TAP  — tap to arm, swing, tap again to throw. The release is a deliberate press.
144	 *
145	 * TAP exists because lifting a finger mid-swing is an imprecise moment: the thumb
146	 * leaves the glass whenever the swing shakes it loose, not necessarily when the
147	 * player means to let go. A second tap is a positive action they choose to make.
148	 */
149	export const ThrowGesture = {
150	  HOLD: 'hold',
151	  TAP: 'tap',
152	};
153	
154	/**
155	 * Reduce a whole swing to the handful of numbers Unity needs.
156	 *
157	 * Pure: takes samples, returns a descriptor. No device access, no side effects,
158	 * so it is fully unit testable without a phone.
159	 *
160	 * @param {Array} samples oldest-to-newest, from MotionSource's ring buffer
161	 * @returns {object|null} descriptor, or null if the gesture was too weak to count
162	 */
163	export function computeThrowDescriptor(samples, tuning = ThrowTuning) {
164	  if (!samples || samples.length === 0) return null;
165	
166	  const release = samples[samples.length - 1];
167	  const windowStart = release.t - tuning.swingWindowMs;
168	
169	  // Peak, not integral. Peak matches perceived effort and is far more forgiving
170	  // of the sample rate wobbling, which it does on real phones. Restricted to the
171	  // recent window so a low-rate device cannot reach back past the swing itself.
172	  let peak = null;
173	  for (const sample of samples) {
174	    if (sample.t < windowStart) continue;
175	    if (peak === null || sample.power > peak.power) peak = sample;
176	  }
177	
178	  if (peak === null || peak.power < tuning.minValidPeakAccel) return null;
179	
180	  const releaseDelayMs = Math.abs(release.t - peak.t);
181	
182	  return {
183	    power: normalize01(peak.power, tuning.minPeakAccel, tuning.maxPeakAccel),
184	    timingQuality: 1 - normalize01(releaseDelayMs, 0, tuning.peakWindowMs),
185	    aimDeg: clamp(toGameYaw(release.dYaw), -tuning.maxAimDeg, tuning.maxAimDeg),
186	    attackAngleDeg: clamp(release.dBeta, tuning.minAttackDeg, tuning.maxAttackDeg),
187	    rollDeg: release.dGamma,
188	    spinRate: Math.hypot(
189	      release.rotationRate.alpha,
190	      release.rotationRate.beta,
191	      release.rotationRate.gamma
192	    ),
193	
194	    // Diagnostics — useful on the TV debug readout while tuning, ignored by physics.
195	    peakAccel: peak.power,
196	    releaseDelayMs,
197	    sampleCount: samples.length,
198	  };
199	}
200	
201	/** Cosmetic aim frame. Never authoritative — see the module header. */
202	export function buildAimPayload(sample, seq, tuning = ThrowTuning) {
203	  if (!sample) return null;
204	  return {
205	    type: 'AIM',
206	    seq,
207	    aimDeg: clamp(toGameYaw(sample.dYaw), -tuning.maxAimDeg, tuning.maxAimDeg),
208	    attackAngleDeg: clamp(sample.dBeta, tuning.minAttackDeg, tuning.maxAttackDeg),
209	    rollDeg: sample.dGamma,
210	    windup: normalize01(sample.power, tuning.minPeakAccel, tuning.maxPeakAccel),
211	  };
212	}
213	
214	/**
215	 * Drives the grip/release gesture and owns the AIM stream while gripped.
216	 *
217	 * Deliberately does not know about the network — it calls onAim/onThrow and lets
218	 * the caller decide what to do with them, so this can be tested with plain stubs.
219	 */
220	export class ThrowController {
221	  constructor(motion, {
222	    onAim, onThrow, onStateChange, onExpire,
223	
224	    // Matched to the sensor rate rather than the 20Hz the plan specified. 20Hz means
225	    // every aim frame is up to 50ms stale before it leaves the phone, which during a
226	    // swing is several degrees of error baked in before the network is even involved
227	    // — and the arc has to track the swing accurately, not just smoothly. Still only
228	    // a few KB/s, and only ever for the one player whose turn it is.
229	    aimHz = 60,
230	    gesture = ThrowGesture.TAP,
231	    minArmMs = 150,
232	    maxArmMs = 10_000,
233	  } = {}) {
234	    this.motion = motion;
235	    this.onAim = onAim ?? (() => {});
236	    this.onThrow = onThrow ?? (() => {});
237	    this.onStateChange = onStateChange ?? (() => {});
238	    this.onExpire = onExpire ?? (() => {});
239	    this.aimIntervalMs = 1000 / aimHz;
240	
241	    this.gesture = gesture;
242	
243	    // Shortest gap between arming and throwing. Below this a double-tap, or one
244	    // bouncy tap, would arm and fire in the same motion and launch a rock with no
245	    // swing behind it at all.
246	    this.minArmMs = minArmMs;
247	
248	    // In TAP mode the armed state is invisible — no finger is on the glass — so a
249	    // player who gets distracted mid-turn would otherwise stream aim frames forever
250	    // and stall the match. In HOLD mode the held finger is unambiguous intent, so
251	    // this does not apply there.
252	    this.maxArmMs = maxArmMs;
253	
254	    this.state = ThrowState.IDLE;
255	    this.seq = 0;
256	    this._timer = null;
257	    this._grippedAt = 0;
258	  }
259	
260	  /**
261	   * One tap, dispatched by state: the first arms the throw, the second releases it.
262	   * Only used in TAP mode; HOLD mode drives grip/release directly.
263	   *
264	   * @returns {object|null} the throw descriptor if this tap threw, else null
265	   */
266	  tap() {
267	    if (this.state === ThrowState.IDLE) {
268	      this.grip();
269	      return null;
270	    }
271	
272	    if (performance.now() - this._grippedAt < this.minArmMs) return null;
273	
274	    return this.release();
275	  }
276	
277	  /** Player pressed and held. Captures the aim reference and starts streaming. */
278	  grip() {
279	    if (this.state !== ThrowState.IDLE) return;
280	
281	    this._grippedAt = performance.now();
282	    this.motion.calibrate();
283	    this._setState(ThrowState.GRIPPED);
284	
285	    this._timer = setInterval(() => {
286	      // Only TAP mode can be armed-and-forgotten; see maxArmMs.
287	      if (this.gesture === ThrowGesture.TAP &&
288	          this.maxArmMs > 0 &&
289	          performance.now() - this._grippedAt > this.maxArmMs) {
290	        this.cancel();
291	        this.onExpire();
292	        return;
293	      }
294	
295	      const payload = buildAimPayload(this.motion.latest, ++this.seq);
296	      if (payload) this.onAim(payload);
297	    }, this.aimIntervalMs);
298	  }
299	
300	  /** Player let go. Analyses the swing and emits exactly one THROW. */
301	  release() {
302	    if (this.state !== ThrowState.GRIPPED) return null;
303	
304	    const holdMs = performance.now() - this._grippedAt;
305	
306	    this._stopTimer();
307	    this._setState(ThrowState.IDLE);
308	
309	    const descriptor = computeThrowDescriptor(this.motion.buffer.toArray());
310	    if (descriptor) {
311	      // sampleHz rides along for diagnostics: it is the number that tells you
312	      // whether two platforms are actually feeding the same quality of data.
313	      this.onThrow({
314	        type: 'THROW',
315	        ...descriptor,
316	        sampleHz: Math.round(this.motion.sampleHz ?? 0),
317	      });
318	      return descriptor;
319	    }
320	
321	    // A real device that produced samples but a weak gesture is a fumble, and must
322	    // stay one. Only a device that has never produced a single motion event has no
323	    // sensors at all — a phone sets `latest` within a frame of start(), long before
324	    // anyone can grip, so this branch is unreachable on real hardware.
325	    if (this.motion.latest === null) {
326	      const simulated = computeSimulatedThrowDescriptor(holdMs);
327	      this.onThrow({ type: 'THROW', ...simulated });
328	      return simulated;
329	    }
330	
331	    return null;
332	  }
333	
334	  /** Turn ended or connection dropped mid-grip — abandon without throwing. */
335	  cancel() {
336	    this._stopTimer();
337	    this._setState(ThrowState.IDLE);
338	  }
339	
340	  _stopTimer() {
341	    if (this._timer !== null) {
342	      clearInterval(this._timer);
343	      this._timer = null;
344	    }
345	  }
346	
347	  _setState(next) {
348	    if (this.state === next) return;
349	    this.state = next;
350	    this.onStateChange(next);
351	  }
352	}
