1	/**
2	 * WebSocket client for the phone controller.
3	 *
4	 * The relay serves this page, so the socket URL is derived from the page origin
5	 * rather than configured. That is deliberate: a hardcoded ws:// address would
6	 * break the moment the page is served over HTTPS (mixed content), which is
7	 * exactly the setup motion sensors require.
8	 */
9	
10	export const ConnectionStatus = {
11	  CONNECTING: 'connecting',
12	  CONNECTED: 'connected',
13	  JOINED: 'joined',
14	  RECONNECTING: 'reconnecting',
15	  ERROR: 'error',
16	};
17	
18	/** Same host, protocol upgraded to wss when the page is secure. */
19	export function deriveSocketUrl(loc = window.location) {
20	  const protocol = loc.protocol === 'https:' ? 'wss:' : 'ws:';
21	  return `${protocol}//${loc.host}`;
22	}
23	
24	const BACKOFF_START_MS = 500;
25	const BACKOFF_MAX_MS = 8000;
26	
27	export class RelayConnection {
28	  constructor({ onMessage, onStatus, url } = {}) {
29	    this.url = url ?? deriveSocketUrl();
30	    this.onMessage = onMessage ?? (() => {});
31	    this.onStatus = onStatus ?? (() => {});
32	
33	    this.socket = null;
34	    this.status = null;
35	    this.backoff = BACKOFF_START_MS;
36	    this.closedByUs = false;
37	
38	    // Kept so a dropped connection can re-join the same slot without the player
39	    // retyping anything — phones sleep and lose Wi-Fi constantly at a party.
40	    this.credentials = null;
41	  }
42	
43	  connect() {
44	    this.closedByUs = false;
45	    this._setStatus(this.credentials ? ConnectionStatus.RECONNECTING : ConnectionStatus.CONNECTING);
46	
47	    this.socket = new WebSocket(this.url);
48	
49	    this.socket.onopen = () => {
50	      this.backoff = BACKOFF_START_MS;
51	      this._setStatus(ConnectionStatus.CONNECTED);
52	      if (this.credentials) this._sendJoin();
53	    };
54	
55	    this.socket.onmessage = (event) => {
56	      let message;
57	      try {
58	        message = JSON.parse(event.data);
59	      } catch {
60	        return; // the relay only ever sends JSON; anything else is noise
61	      }
62	      if (message.type === 'JOINED') this._setStatus(ConnectionStatus.JOINED);
63	      this.onMessage(message);
64	    };
65	
66	    this.socket.onclose = () => {
67	      if (this.closedByUs) return;
68	      this._setStatus(ConnectionStatus.RECONNECTING);
69	      setTimeout(() => this.connect(), this.backoff);
70	      this.backoff = Math.min(this.backoff * 2, BACKOFF_MAX_MS);
71	    };
72	
73	    this.socket.onerror = () => this._setStatus(ConnectionStatus.ERROR);
74	  }
75	
76	  joinRoom(roomCode, playerId) {
77	    this.credentials = { roomCode, playerId };
78	    this._sendJoin();
79	  }
80	
81	  _sendJoin() {
82	    if (!this.credentials) return;
83	    this.send({ type: 'JOIN_ROOM', ...this.credentials });
84	  }
85	
86	  /** Fire-and-forget. Dropped silently while disconnected — AIM frames are lossy by design. */
87	  send(payload) {
88	    if (this.socket?.readyState !== WebSocket.OPEN) return false;
89	    this.socket.send(JSON.stringify(payload));
90	    return true;
91	  }
92	
93	  close() {
94	    this.closedByUs = true;
95	    this.socket?.close();
96	  }
97	
98	  _setStatus(status) {
99	    if (this.status === status) return;
100	    this.status = status;
101	    this.onStatus(status);
102	  }
103	}
