5	
6	namespace Game
7	{
8	    /// <summary>
9	    /// Live trajectory preview on the TV while a player aims.
10	    /// </summary>
11	    /// <remarks>
12	    /// Smoothing is not polish here, it is what makes the feature work: AIM frames
13	    /// arrive at only ~20Hz over a jittery connection, so applying them raw looks
14	    /// choppy. Values are smoothed toward their targets every frame instead.
15	    ///
16	    /// The arc comes from SkipPhysics.Predict — the same solver the live throw uses,
17	    /// so what a player sees is what they get. It runs at a nominal power because the
18	    /// real power is unknown until release; the arc teaches the ~20 degree angle
19	    /// rather than promising an exact landing spot.
20	    ///
21	    /// This never publishes gameplay events. Prediction is speculative by definition.
22	    /// </remarks>
23	    public class AimPreview : MonoBehaviour
24	    {
25	        [Header("Setup")]
26	        [Tooltip("Leave empty to use a runtime default.")]
27	        [SerializeField] private SkipTuning tuning;
28	        [SerializeField] private Transform throwOrigin;
29	
30	        [Tooltip("Spawn placeholder water and frame the camera. Scaffolding until the real lake exists.")]
31	        [SerializeField] private bool createPlaceholderScene = true;
32	
33	        [Header("Feel")]
34	        [Tooltip("Power the arc is drawn at. Real power is unknown until release.")]
35	        [Range(0f, 1f)] [SerializeField] private float previewPower = 0.7f;
36	
37	        [Tooltip("Nominal spin for the arc, same reasoning as preview power — actual spin " +
38	                 "is only known at release. Must be roughly what real throws produce: spin " +
39	                 "buys angle tolerance, so predicting with zero spin draws a far harsher " +
40	                 "throw than the player will actually get. Measured throws land near 1000.")]
41	        [SerializeField] private float previewSpin = 800f;
42	        [Tooltip("Lag deliberately traded against jitter. SmoothDamp trails its target by " +
43	                 "roughly this long, which during a fast swing is degrees of error — so " +
44	                 "this wants to be only just large enough to hide packet jitter, no more. " +
45	                 "Sized against a 60Hz aim stream; raise it if the arc looks noisy.")]
46	        [SerializeField] private float smoothTime = 0.035f;
47	        [Tooltip("Hide the preview after this long with no aim frames — surfaces a dropped phone. " +
48	                 "Also how long the arc lingers after a throw, which is the only chance the " +
49	                 "player gets to compare the line they were shown against the rock that left.")]
50	        [SerializeField] private float staleAfterSeconds = 1f;
51	
52	        public int PredictedSkips { get; private set; }
53	        public float PredictedDistance { get; private set; }
54	        public bool HasSignal { get; private set; }
55	
56	        /// <summary>Shared with RockLauncher so preview and live throw use one rig.</summary>
57	        public Transform ThrowOrigin => throwOrigin;
58	        public SkipTuning Tuning => tuning;
